<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,TutorGroup,TrainingSession,TimetableRoom as Room,TimetableStaffWindow as Window,TimetablePlan as Plan,TimetablePlanEntry as Entry};
use App\Support\{CentrePlanning as P,CentreTimetable as T,ReviewedImports};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Mail,Http};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class CentrePlanningTest extends TestCase {
 use LazilyRefreshDatabase;
 private function fixture():array {
  $admin=User::factory()->create(['role'=>'admin']);$tutor=User::factory()->create(['role'=>'tutor']);$staff=User::factory()->create(['role'=>'staff']);$planner=User::factory()->create(['role'=>'manager']);P::grant($admin,1,$planner,0,true);$group=TutorGroup::factory()->create(['tutor_id'=>$tutor->id]);$a=Apprentice::factory()->create(['tutor_group_id'=>$group->id,'tutor_id'=>$tutor->id]);$room=Room::where('site','Doncaster')->firstOrFail();P::room($admin,1,$room,1,['capacity'=>8,'uses'=>['Teaching','Review','Admin'],'active'=>true]);$room->refresh();$date=today()->addDays(7)->startOfWeek()->addDay()->toDateString();$dates=P::dates($date,2);P::windows($admin,1,$tutor,$dates,ReviewedImports::hash(P::windowSource($tutor,$dates)),true,'08:00','18:00');$d=['staff_id'=>$tutor->id,'date'=>$date,'weeks'=>2,'start'=>'09:00','end'=>'12:00','kind'=>'Teaching','site'=>'Doncaster','room_id'=>$room->id,'group_id'=>$group->id,'title'=>'Fictional engine training','headcount'=>4];return compact('admin','tutor','staff','planner','group','a','room','date','dates','d');
 }
 private function draft(array $f,?array $d=null):Plan {return P::save($f['planner'],1,null,0,(string)Str::uuid(),$d??$f['d']);}
 private function publish(array $f,?array $d=null):Plan {$p=$this->draft($f,$d);P::check($f['planner'],1,$p,1,true);P::publish($f['planner'],1,$p->refresh(),2);return $p->refresh();}
 private function reject(callable $f):void {try{$f();$this->fail('Expected checked rejection');}catch(ValidationException $e){$this->assertNotEmpty($e->errors());}}
 private function work(array $f,User $u):void {P::windows($f['admin'],1,$u,$f['dates'],ReviewedImports::hash(P::windowSource($u,$f['dates'])),true,'08:00','18:00');}
 private function register(array $f):TrainingSession {return TrainingSession::factory()->create(['tutor_group_id'=>$f['group']->id,'created_by'=>$f['admin']->id,'session_date'=>$f['date'],'start_time'=>'09:00','end_time'=>'12:00','members'=>[$f['a']->id]]);}
 public function test_eighteen_rooms_without_invented_capacity():void {$this->assertDatabaseCount('timetable_rooms',18);$this->assertSame(4,Room::where('site','Sheffield')->count());$this->assertSame(14,Room::where('site','Doncaster')->count());$this->assertSame(18,Room::whereNull('capacity')->count());$this->assertDatabaseHas('timetable_rooms',['name'=>'FLT Training Room']);}
 public function test_planning_permission_preserves_primary_role_and_other_boundaries():void {$f=$this->fixture();$this->assertTrue(P::allowed($f['planner']));$this->assertSame('manager',$f['planner']->fresh()->role);$this->actingAs($f['planner'])->get('/centre-planning')->assertOk();$this->get('/portal-setup')->assertForbidden();}
 public function test_staff_only_see_own_published_timetable():void {$f=$this->fixture();$p=$this->draft($f);$this->actingAs($f['staff'])->get('/centre-planning')->assertOk()->assertDontSee($f['tutor']->name);foreach(['/centre-planning/plans','/centre-planning/plans/'.$p->id,'/centre-planning/setup','/centre-planning.json']as$url){$this->get($url)->assertForbidden();}}
 public function test_apprentice_employer_unassigned_are_denied():void {$this->fixture();foreach(['apprentice','employer','unassigned']as$role){$this->actingAs(User::factory()->create(['role'=>$role]))->get('/centre-planning')->assertForbidden();}}
 public function test_planner_cannot_grant_access():void {$f=$this->fixture();$this->actingAs($f['planner'])->post('/centre-planning/access/'.$f['staff']->id,['version'=>0,'active'=>1,'confirmed'=>1])->assertForbidden();$this->assertFalse(P::allowed($f['staff']));}
 public function test_revocation_raw_tamper_and_role_drift_fail_closed():void {$f=$this->fixture();$f['planner']->forceFill(['role'=>'mentor'])->save();$this->assertFalse(P::allowed($f['planner']->fresh()));$f['planner']->forceFill(['role'=>'manager'])->save();P::grant($f['admin'],1,$f['planner'],1,false);DB::table('timetable_planner_access')->update(['active'=>true]);$this->assertFalse(P::allowed($f['planner']->fresh()));}
 public function test_working_window_preview_rejects_stale_updates():void {$f=$this->fixture();$hash=ReviewedImports::hash(P::windowSource($f['tutor'],$f['dates']));P::windows($f['admin'],1,$f['tutor'],$f['dates'],$hash,true,'08:30','17:00');$this->reject(fn()=>P::windows($f['admin'],1,$f['tutor'],$f['dates'],$hash,true,'09:00','17:00'));$this->assertSame(2,Window::where('user_id',$f['tutor']->id)->count());}
 public function test_unknown_nonworking_and_corrupt_windows_never_invent_free_time():void {$f=$this->fixture();$b=T::board($f['admin'],$f['date'],'staff',null,$f['staff']->id);$this->assertNull($b['cells'][$f['staff']->id][$f['date']]['stats']['available']);P::windows($f['admin'],1,$f['tutor'],[$f['date']],ReviewedImports::hash(P::windowSource($f['tutor'],[$f['date']])),false,null,null);$b=T::board($f['admin'],$f['date'],'staff',null,$f['tutor']->id);$this->assertSame(0,$b['cells'][$f['tutor']->id][$f['date']]['stats']['available']);DB::table('timetable_staff_windows')->update(['version'=>9]);$b=T::board($f['admin'],$f['date'],'staff',null,$f['tutor']->id);$this->assertFalse($b['cells'][$f['tutor']->id][$f['date']]['known']);}
 public function test_encrypted_draft_hidden_from_grid():void {$f=$this->fixture();$p=$this->draft($f);$this->assertTrue(P::intact($p));$this->assertStringNotContainsString('Fictional engine',DB::table('timetable_plans')->value('source'));$this->assertSame([],T::board($f['admin'],$f['date'])['rows']);}
 public function test_exact_replay_is_idempotent_changed_replay_rejected():void {$f=$this->fixture();$token=(string)Str::uuid();$a=P::save($f['planner'],1,null,0,$token,$f['d']);$b=P::save($f['planner'],1,null,0,$token,$f['d']);$this->assertSame($a->id,$b->id);$this->assertDatabaseCount('timetable_plan_entries',2);$d=$f['d'];$d['title']='Changed';$this->reject(fn()=>P::save($f['planner'],1,null,0,$token,$d));}
 public function test_invalid_dates_recurrence_time_site_and_title_rejected():void {$f=$this->fixture();foreach([['weeks'=>54],['date'=>'2027-02-30'],['start'=>'25:00'],['end'=>'08:00'],['site'=>'Sheffield'],['title'=>"Unsafe\nname"]]as$bad){$this->reject(fn()=>$this->draft($f,array_replace($f['d'],$bad)));}}
 public function test_teaching_requires_current_group_primary_tutor():void {$f=$this->fixture();$d=$f['d'];$d['staff_id']=$f['staff']->id;$this->reject(fn()=>$this->draft($f,$d));}
 public function test_two_exact_occurrences_checked_published_no_extras():void {$f=$this->fixture();$p=$this->publish($f);$this->assertTrue(P::published($p));$this->assertSame(3,$p->version);$this->assertCount(2,P::liveRows($p));$this->assertCount(1,T::board($f['admin'],$f['date'])['rows']);}
 public function test_publication_requires_prior_check_and_current_version():void {$f=$this->fixture();$p=$this->draft($f);$this->reject(fn()=>P::publish($f['planner'],1,$p,1));P::check($f['planner'],1,$p,1,true);$this->reject(fn()=>P::publish($f['planner'],1,$p->refresh(),1));}
 public function test_unknown_or_unsuitable_room_blocks_check():void {$f=$this->fixture();$room=Room::where('site','Doncaster')->where('id','!=',$f['room']->id)->first();$d=$f['d'];$d['room_id']=$room->id;$p=$this->draft($f,$d);$this->reject(fn()=>P::check($f['planner'],1,$p,1,true));P::room($f['admin'],1,$room,1,['capacity'=>8,'uses'=>['Admin'],'active'=>true]);$p=P::save($f['planner'],1,$p,1,(string)Str::uuid(),$d);$this->reject(fn()=>P::check($f['planner'],1,$p,2,true));}
 public function test_room_capacity_and_current_group_headcount_checked():void {$f=$this->fixture();$d=$f['d'];$d['headcount']=9;$p=$this->draft($f,$d);$this->reject(fn()=>P::check($f['planner'],1,$p,1,true));for($i=0;$i<4;$i++){Apprentice::factory()->create(['tutor_group_id'=>$f['group']->id]);}$p=P::save($f['planner'],1,$p,1,(string)Str::uuid(),$f['d']);$this->reject(fn()=>P::check($f['planner'],1,$p,2,true));}
 public function test_outside_working_window_blocks_check():void {$f=$this->fixture();$d=$f['d'];$d['start']='07:30';$p=$this->draft($f,$d);$this->reject(fn()=>P::check($f['planner'],1,$p,1,true));}
 public function test_staff_room_and_group_clashes_blocked_adjacent_slot_allowed():void {$f=$this->fixture();$this->publish($f);$p=$this->draft($f);$this->reject(fn()=>P::check($f['planner'],1,$p,1,true));$this->work($f,$f['staff']);$d=array_replace($f['d'],['staff_id'=>$f['staff']->id,'kind'=>'Admin','group_id'=>null,'headcount'=>null]);$p=$this->draft($f,$d);$this->reject(fn()=>P::check($f['planner'],1,$p,1,true));$d=$f['d'];$d['start']='12:00';$d['end']='13:00';$this->assertTrue(P::published($this->publish($f,$d)));}
 public function test_competing_publication_invalidates_prior_check():void {$f=$this->fixture();$p=$this->draft($f);P::check($f['planner'],1,$p,1,true);$this->publish($f);$this->reject(fn()=>P::publish($f['planner'],1,$p->refresh(),2));}
 public function test_room_and_checker_auth_changes_hold_publication():void {$f=$this->fixture();$p=$this->draft($f);P::check($f['planner'],1,$p,1,true);P::room($f['admin'],1,$f['room'],2,['capacity'=>10,'uses'=>['Teaching'],'active'=>true]);$this->reject(fn()=>P::publish($f['planner'],1,$p->refresh(),2));$p=P::save($f['planner'],1,$p,2,(string)Str::uuid(),$f['d']);P::check($f['planner'],1,$p,3,true);$f['planner']->increment('auth_version');$this->reject(fn()=>P::publish($f['admin'],1,$p->refresh(),4));}
 public function test_stale_published_source_remains_reserved():void {$f=$this->fixture();$p=$this->publish($f);$f['group']->increment('record_version');$rows=P::busy([$f['date']])['rows'];$this->assertCount(1,$rows);$this->assertTrue($rows[0]['stale']);$this->assertTrue(P::published($p));}
 public function test_raw_entry_and_publication_forgery_held():void {$f=$this->fixture();$p=$this->draft($f);DB::table('timetable_plans')->update(['state'=>'Published']);$this->assertFalse(P::published($p->refresh()));$this->assertNotEmpty(P::busy([$f['date']])['uncertain']);$b=T::board($f['admin'],$f['date'],'staff',null,$f['tutor']->id);$this->assertNull($b['cells'][$f['tutor']->id][$f['date']]['stats']['available']);DB::table('timetable_plan_entries')->update(['end_time'=>'15:00']);$this->assertFalse(P::intact($p));}
 public function test_future_withdrawal_preserves_started_planned_history():void {$f=$this->fixture();$p=$this->publish($f);$this->travelTo(\Carbon\Carbon::parse($f['date'].' 13:00'));P::withdraw($f['planner'],1,$p,3,'Future plan changed');$this->assertTrue(P::withdrawn($p->refresh()));$this->assertCount(1,P::liveRows($p));$this->assertSame($f['date'],P::liveRows($p)[0]['work_date']);}
