 public function test_cross_site_requires_configured_minimum_and_explicit_travel():void {$f=$this->fixture();$this->publish($f);$d=array_replace($f['d'],['kind'=>'Admin','group_id'=>null,'room_id'=>null,'site'=>'Sheffield','start'=>'14:00','end'=>'15:00','headcount'=>null]);$p=$this->draft($f,$d);$this->reject(fn()=>P::check($f['planner'],1,$p,1,true));config(['timetable_planning.cross_site_minutes'=>60]);$p=P::save($f['planner'],1,$p,1,(string)Str::uuid(),$d);$this->reject(fn()=>P::check($f['planner'],1,$p,2,true));$travel=array_replace($f['d'],['kind'=>'Travel','site'=>'Between centres','group_id'=>null,'room_id'=>null,'headcount'=>null,'start'=>'12:00','end'=>'13:00']);$this->publish($f,$travel);P::check($f['planner'],1,$p,2,true);P::publish($f['planner'],1,$p->refresh(),3);$this->assertTrue(P::published($p->refresh()));}
 public function test_existing_register_reserves_time_unknown_location_warning_acknowledged():void {$f=$this->fixture();$s=$this->register($f);$p=$this->draft($f);$this->reject(fn()=>P::check($f['planner'],1,$p,1,true));$d=$f['d'];$d['start']='14:00';$d['end']='15:00';$p=$this->draft($f,$d);$this->reject(fn()=>P::check($f['planner'],1,$p,1,false));P::check($f['planner'],1,$p,1,true);$this->assertNotEmpty($p->refresh()->check_proof['warnings']);$s->end_time='08:00';$s->save();$this->assertNotEmpty(P::busy([$f['date']])['uncertain']);$board=T::board($f['admin'],$f['date'],'staff',null,$f['tutor']->id);$this->assertNull($board['cells'][$f['tutor']->id][$f['date']]['stats']['available']);}
 public function test_board_actual_time_position_gaps_and_workload():void {$f=$this->fixture();$this->publish($f);$b=T::board($f['admin'],$f['date'],'staff',null,$f['tutor']->id);$c=$b['cells'][$f['tutor']->id][$f['date']];$this->assertSame(600,$c['stats']['capacity']);$this->assertSame(180,$c['stats']['teaching']);$this->assertSame(420,$c['stats']['available']);$this->assertSame([[480,540],[720,1080]],$c['gaps']);$this->assertEquals(10,$c['positions'][0]['top']);$this->assertEquals(30,$c['positions'][0]['height']);}
 public function test_overlap_lanes_and_union_minutes_avoid_hidden_or_double_counted_items():void {$f=$this->fixture();$x=T::layout([['start_time'=>'09:00','end_time'=>'11:00','key'=>'a'],['start_time'=>'10:00','end_time'=>'12:00','key'=>'b']],480,1080);$this->assertEquals(50,$x[0]['width']);$this->assertEquals(50,$x[1]['left']);$this->assertSame(180,T::unionMinutes([[540,660],[600,720]]));}
 public function test_site_filter_does_not_create_false_staff_gaps():void {$f=$this->fixture();$this->publish($f);$b=T::board($f['admin'],$f['date'],'staff','Sheffield',$f['tutor']->id);$this->assertSame([],$b['rows']);$this->assertSame(420,$b['cells'][$f['tutor']->id][$f['date']]['stats']['available']);}
 public function test_room_group_and_forced_own_staff_views():void {$f=$this->fixture();$this->publish($f);foreach([['room',$f['room']->id],['group',$f['group']->id]]as[$mode,$id]){$this->assertCount(1,T::board($f['admin'],$f['date'],$mode,null,$id)['rows']);}$b=T::board($f['tutor'],$f['date'],'room','Sheffield',$f['room']->id);$this->assertFalse($b['planner']);$this->assertSame('staff',$b['mode']);$this->assertSame($f['tutor']->id,$b['selected']);}
 public function test_link_collapses_register_duplicate_and_preserves_room():void {$f=$this->fixture();$p=$this->publish($f);$s=$this->register($f);$e=Entry::where('plan_id',$p->id)->orderBy('work_date')->first();$this->assertCount(2,P::busy([$f['date']])['rows']);P::link($f['planner'],1,$e,3,$s,1);$this->assertTrue(P::linkCurrent($e->refresh(),$p));$rows=P::busy([$f['date']])['rows'];$this->assertCount(1,$rows);$this->assertSame($f['room']->id,$rows[0]['room_id']);$this->assertSame($s->id,$rows[0]['linked_session']);}
 public function test_register_change_invalidates_link_without_changing_source():void {$f=$this->fixture();$p=$this->publish($f);$s=$this->register($f);$e=Entry::where('plan_id',$p->id)->orderBy('work_date')->first();P::link($f['planner'],1,$e,3,$s,1);$s->increment('version');$this->assertFalse(P::linkCurrent($e->refresh(),$p));$this->assertCount(2,P::busy([$f['date']])['rows']);$this->assertSame('09:00',$s->refresh()->start_time);}
 public function test_wrong_roster_or_stale_register_version_not_linked():void {$f=$this->fixture();$p=$this->publish($f);$s=$this->register($f);$e=Entry::where('plan_id',$p->id)->first();$this->reject(fn()=>P::link($f['planner'],1,$e,3,$s,9));$s->members=[];$s->save();$this->reject(fn()=>P::link($f['planner'],1,$e,3,$s,1));}
 public function test_unlink_retains_register_and_creates_no_marks():void {$f=$this->fixture();$p=$this->publish($f);$s=$this->register($f);$e=Entry::where('plan_id',$p->id)->orderBy('work_date')->first();P::link($f['planner'],1,$e,3,$s,1);$e->refresh();P::unlink($f['planner'],1,$e,3,ReviewedImports::hash($e->link_proof));$this->assertNull($e->refresh()->training_session_id);$this->assertDatabaseHas('training_sessions',['id'=>$s->id,'state'=>'Planned']);$this->assertDatabaseCount('attendance_marks',0);}
 public function test_mandatory_audit_failure_rolls_back_publication():void {$f=$this->fixture();$p=$this->draft($f);P::check($f['planner'],1,$p,1,true);AuditFault::install('planning_fault','timetable_planning_events','Fictional failure','plan_published');try{P::publish($f['planner'],1,$p->refresh(),2);$this->fail('Expected DB failure');}catch(\Illuminate\Database\QueryException){$this->assertSame('Draft',$p->refresh()->state);$this->assertNull($p->publication);}}
 public function test_no_training_attendance_completion_otj_or_messages_created():void {Mail::fake();Http::preventStrayRequests();$f=$this->fixture();$p=$this->publish($f);P::withdraw($f['planner'],1,$p,3,'Fictional change');foreach(['training_sessions','attendance_marks','signed_review_records','historical_otj_records']as$t){$this->assertDatabaseCount($t,0);}Mail::assertNothingSent();Http::assertNothingSent();}
 public function test_flexible_day_selection_opens_the_existing_workflow_with_staff_and_date(): void
 {
     $fixture = $this->fixture();
     $selection = ['staff_id' => $fixture['tutor']->id, 'date' => $fixture['date']];
     $flexible = route('timetable-duties.flexible', $selection);
     $save = route('centre-planning.save');
     $new = route('centre-planning.form');
     $this->actingAs($fixture['planner'])->get($new)->assertOk()
         ->assertSee('Flexible day')->assertSee('Timetable title')->assertDontSee('Safe title');
     $this->get(route('centre-planning.form', $selection + ['kind' => 'Flexible day']))->assertRedirect($flexible);
     $this->post($save, $selection + ['kind' => 'Flexible day'])->assertRedirect($flexible);
     $this->get($flexible)->assertOk()->assertSee($fixture['date']);
     $this->assertDatabaseCount('timetable_plans', 0);
     $this->assertDatabaseCount('timetable_flexible_days', 0);
     $this->actingAs($fixture['tutor'])->post($save, $selection + ['kind' => 'Flexible day'])->assertForbidden();
 }

 public function test_http_all_forms_board_and_private_headers_render():void {$f=$this->fixture();$p=$this->publish($f);$this->actingAs($f['planner']);foreach(['/centre-planning?week='.$f['date'],'/centre-planning/setup','/centre-planning/working-time?staff_id='.$f['tutor']->id.'&date='.$f['date'],'/centre-planning/plans','/centre-planning/plans/new','/centre-planning/plans/'.$p->id]as$url){$this->get($url)->assertOk()->assertHeader('Referrer-Policy','no-referrer');}$this->get('/centre-planning?week='.$f['date'])->assertSee('Available')->assertSee('Accessible item list')->assertSee($f['tutor']->name);}
 public function test_status_export_omits_private_rosters_and_activity_titles():void {$f=$this->fixture();$this->publish($f);$this->actingAs($f['planner'])->get('/centre-planning.json?week='.$f['date'])->assertOk()->assertJsonPath('actual_attendance_or_otj',false)->assertDontSee($f['a']->reference)->assertDontSee('Fictional engine training');}
 public function test_missing_confirmation_writes_no_check():void {$f=$this->fixture();$p=$this->draft($f);$this->actingAs($f['planner'])->post('/centre-planning/plans/'.$p->id.'/decision',['version'=>1,'action'=>'check'])->assertSessionHasErrors('confirmed');$this->assertNull($p->refresh()->check_proof);}
